/* Reconciled source questionnaire; only_if becomes explicit visibility gates. */
function buildProcurementQuestionnaire(source=PRODUCTION_PROCUREMENT_SOURCE){const pages=[{key:'load',title:'Load details',scope:'load',questions:source.load_form.questions},...source.pages.map(p=>({...p,title:p.title||'Identity',scope:'animal'}))],records=pages.flatMap((p,pi)=>p.questions.map((q,qi)=>({q,page:p,pageIndex:pi,order:qi,id:'proc-'+p.scope+'-'+q.id}))),lookup=new Map(records.map(r=>[r.page.scope+':'+r.q.id,r]));const nodes=[{id:'start',type:'start',label:'Begin Animal Purchase Inspection',x:220,y:20,next:''}],questionNodes=new Map(),entries=new Map();for(const r of records){const q=r.q,type={text:'Text',vendor:'Catalogue',choice:'Single choice',multi:'Multiple choice',number:'Number',media:'Photo or video'}[q.kind]||'Text';const n={id:r.id,type:'question',label:q.title,answer:type,required:q.required!==false,hint:q.hint||'',options:q.options?structuredClone(q.options):undefined,choices:'',unit:q.unit||'',unitOptional:!q.unit,min:q.min??null,max:q.max??null,catalogueSourceId:q.kind==='vendor'?'source-vendors':'',allowOther:!!q.allow_other,proof:q.kind==='media'?{accepts:structuredClone(q.accepts||[]),maxFiles:q.max_files,minFiles:q.required?1:0,slot:q.slot}:undefined,sourceQuestionId:q.id,sourcePage:r.page.key,sourcePageTitle:r.page.title,sourceScope:r.page.scope,sourceOrder:records.indexOf(r),sourceMetadata:structuredClone(q),importUnsupported:[],x:220,y:180+records.indexOf(r)*185,next:''};if(!['text','vendor','choice','multi','number','media'].includes(q.kind))n.importUnsupported.push('Unknown source kind '+q.kind);if(q.source_id_verified===false)n.sourceWarnings=['Exact production question key is not verified; local preview ID only'];questionNodes.set(r.id,n);nodes.push(n)}const end={id:'end',type:'end',label:'Complete Animal Purchase Inspection',x:220,y:180+records.length*185};nodes.push(end);function guards(r,seen=new Set()){const cond=r.q.only_if;if(!cond)return[];const parent=lookup.get(r.page.scope+':'+cond.question_id);if(!parent||seen.has(parent.id)){questionNodes.get(r.id).importUnsupported.push('Unresolvable source visibility condition');return[]}return [...guards(parent,new Set([...seen,r.id])),{parent,value:cond.value}]}
for(const r of records){const g=guards(r);const conditions=g.map((guard,i)=>({id:'visibility-'+r.id+'-'+i,type:'condition',label:'Show '+r.q.title,source:guard.parent.id,op:'=',value:guard.value,yes:'',no:'',x:570+i*295,y:questionNodes.get(r.id).y-100,visibilityFor:r.id,sourceDerived:true}));conditions.forEach((n,i)=>n.yes=conditions[i+1]?.id||r.id);nodes.push(...conditions);entries.set(r.id,conditions[0]?.id||r.id)}records.forEach((r,i)=>{const next=entries.get(records[i+1]?.id)||'end';questionNodes.get(r.id).next=next;nodes.filter(n=>n.visibilityFor===r.id).forEach(n=>n.no=next)});nodes[0].next=entries.get(records[0].id);return {title:'Animal Purchase Inspection',version:0,published:null,nodes,sourceBaseline:structuredClone(source),sourceProvenance:structuredClone(source.provenance),sourceImport:true,sourcePages:pages.map(p=>({key:p.key,title:p.title,scope:p.scope,count:p.questions.length}))}}
function procurementSourceForImport(){return typeof CURRENT_PROCUREMENT_SOURCE!=='undefined'?CURRENT_PROCUREMENT_SOURCE:PRODUCTION_PROCUREMENT_SOURCE}
function procurementImportIsCurrent(s,source=procurementSourceForImport()){return !!(s?.sourceImport&&s.sourceProvenance?.observed_published_version===source.provenance?.observed_published_version&&s.sourcePages?.reduce((n,p)=>n+p.count,0)===(source.load_form.questions.length+source.pages.reduce((n,p)=>n+p.questions.length,0)))}
function ensureProcurementQuestionnaire(){if(typeof PRODUCTION_PROCUREMENT_SOURCE==='undefined')return;const source=procurementSourceForImport(),existing=state.sops?.Procurement;const stale=!procurementImportIsCurrent(existing,source)||existing?.title==='Procurement daily check'||existing?.title==='Animal arrival inspection'||(existing?.nodes||[]).some(n=>n.label==='Open Animal Purchase Inspection pages');if(!stale)return;state.archivedSops??={};state.archivedSops.Procurement??=[];if(existing&&!state.archivedSops.Procurement.some(s=>s?.title===existing.title&&s?.nodes?.length===existing.nodes?.length))state.archivedSops.Procurement.push(structuredClone(existing));state.sops??={};state.sops.Procurement=buildProcurementQuestionnaire(source);state.procurementSourceImported=true;state.seedVersion=4;persist()}
function procurementSourceDialog(){const s=sop();if(!s.sourceBaseline)return;modal('Read-only source baseline',`<div class="notice">Observed published version ${s.sourceProvenance.observed_published_version}; ${s.sourceProvenance.exact_published_dsl_export?'exported read-only from the published staging form and cross-checked in the live UI.':'reconciled from live UI and repository seed; this older baseline is not an exported production DSL.'} Editable changes live in a separate local draft.</div><p>${esc(s.sourceProvenance.reconciliation_status)}</p>${s.sourcePages.map(p=>`<div class="linkline"><b>${esc(p.title)}</b><span>${p.count} questions · ${p.scope}</span></div>`).join('')}<details><summary>Exact preserved source document</summary><pre>${esc(JSON.stringify(s.sourceBaseline,null,2))}</pre></details>`,true)}
const procPreviousEditor=renderEditor;renderEditor=function(){procPreviousEditor();if(sop().sourceImport&&$('.toolbar')){$('.toolbar').insertAdjacentHTML('beforeend','<button onclick="procurementSourceDialog()">Source baseline</button>');const hint=$('#main>.hint');if(hint)hint.textContent=`Imported local draft · ${sop().sourcePages.filter(p=>p.scope==='load').reduce((n,p)=>n+p.count,0)} load questions + ${sop().sourcePages.filter(p=>p.scope==='animal').reduce((n,p)=>n+p.count,0)} animal questions · ${sop().sourcePages.filter(p=>p.scope==='animal').length} animal pages. Conditional questions follow the source form. Local publication stays in this browser.`}};
const procPreviousInspect=inspect;inspect=function(){procPreviousInspect();const q=sop().nodes.find(n=>n.id===selected),p=$('#inspector');if(!q||!p)return;if(q.sourcePageTitle)p.insertAdjacentHTML('afterbegin',`<div class="notice">${esc(q.sourcePageTitle)} · ${esc(q.sourceScope)}<br>Source question: ${esc(q.sourceQuestionId)}</div>`);if(q.proof)p.insertAdjacentHTML('beforeend',`<div class="notice">Proof slot: ${esc(q.proof.slot)}<br>Accepts: ${q.proof.accepts.map(esc).join(' or ')}<br>Maximum files: ${q.proof.maxFiles} · Minimum: ${q.proof.minFiles}</div>`);const answer=p.querySelector('[aria-label="Answer type"]');if(answer&&q.answer==='Photo or video'&&!Array.from(answer.options).some(o=>o.value===q.answer)){answer.insertAdjacentHTML('beforeend','<option>Photo or video</option>');answer.value=q.answer}if(q.unit){const unit=p.querySelector('[aria-label="Unit"]');if(unit&&!Array.from(unit.options).some(o=>o.value===q.unit)){unit.insertAdjacentHTML('beforeend',`<option>${esc(q.unit)}</option>`);unit.value=q.unit}}};
const procPreviousSimInput=simInput;simInput=function(q){if(['Photo','Video','Photo or video'].includes(q.answer)){const proof=questionProofSettings(q);return `${q.hint?`<p>${esc(q.hint)}</p>`:''}<input id="simvalue" aria-label="Operator answer" type="file" accept="${proof.accepts.map(t=>t==='photo'?'image/*':'video/*').join(',')}" ${proof.maxFiles>1?'multiple':''}><div class="hint">${proof.accepts.map(esc).join(' or ')||'Photo or video'} · up to ${proof.maxFiles} files. Local file names only; nothing uploads.</div>`}const base=procPreviousSimInput(q);return base+(q.allowOther?'<label class="field" style="margin-top:14px"><span>If Other selected, please specify</span><input id="simother" aria-label="Other answer details"></label>':'')};
const procPreviousSimAnswer=simAnswer;simAnswer=function(){const q=sim?.nodes.find(n=>n.id===sim.id);if(!q)return;if(['Photo','Video','Photo or video'].includes(q.answer)){const proof=questionProofSettings(q);const files=Array.from($('#simvalue')?.files||[]),min=q.required===false?(files.length?Math.max(1,q.proofRequiredMin||proof.minFiles||1):0):Math.max(1,proof.minFiles||1),max=proof.maxFiles;if(files.length<min||files.length>max){$('#simerror').textContent=`Choose ${min} to ${max} files.`;return}if(files.some(f=>f.type&&!proof.accepts.some(t=>f.type.startsWith(t==='photo'?'image/':'video/')))){$('#simerror').textContent='Choose only the permitted photo or video files.';return}sim.answers[q.id]=files.map(f=>f.name);sim.path.push(q.label+': '+(files.map(f=>f.name).join(', ')||'skipped'));sim.id=q.next;renderSim();return}if(q.allowOther){const selected=q.answer==='Multiple choice'?Array.from(document.querySelectorAll('.simcheck:checked')).map(el=>el.value):[$('#simvalue')?.value];if(selected.includes('other')){const detail=$('#simother')?.value.trim();if(!detail){$('#simerror').textContent='Describe the Other answer before continuing.';return}(sim.otherAnswers??={})[q.id]=detail}}procPreviousSimAnswer()};
const procPreviousList=renderQuestionList;renderQuestionList=function(){procPreviousList();if(!sop().sourceImport)return;const rows=document.querySelectorAll('.question-list-row'),ordered=questionnaireOrder(sop().nodes);let previous='';rows.forEach((row,index)=>{const n=ordered[index];if(n.sourcePageTitle&&n.sourcePageTitle!==previous){row.insertAdjacentHTML('beforebegin',`<div class="question-page-heading"><h3>${esc(n.sourcePageTitle)}</h3><span>${esc(n.sourceScope)} · source page ${esc(n.sourcePage)}</span></div>`);previous=n.sourcePageTitle}})};
ensureProcurementQuestionnaire();

function sourceVisibilityGateUnchanged(s,n){if(!n.sourceDerived||n.type!=='condition'||n.op!=='=')return false;const target=s.nodes.find(q=>q.id===n.visibilityFor);if(!target?.sourceMetadata)return false;let q=target,seen=new Set();while(q?.sourceMetadata?.only_if&&!seen.has(q.id)){seen.add(q.id);const cond=q.sourceMetadata.only_if,parent=s.nodes.find(p=>p.type==='question'&&p.sourceScope===q.sourceScope&&p.sourceQuestionId===cond.question_id);if(!parent)return false;if(n.source===parent.id&&String(n.value)===String(cond.value))return true;q=parent}return false}
const sourceVisibilityValidate=validateWorkflow;validateWorkflow=function(s,m=current){const errors=sourceVisibilityValidate(s,m);return errors.filter(e=>{if(!e.endsWith(': source answer must be collected before this decision.'))return true;const candidates=s.nodes.filter(n=>e===n.label+': source answer must be collected before this decision.');return !candidates.length||!candidates.every(n=>sourceVisibilityGateUnchanged(s,n))})};
function refreshProcurementImportMetadata(){for(const s of [state.sops.Procurement,...(state.archivedSops?.Procurement||[])].filter(s=>s?.sourceImport)){for(const q of s.nodes){if(q.sourceMetadata?.kind==='number'&&!q.sourceMetadata.unit&&!q.unit)q.unitOptional=true;if(q.sourceMetadata?.source_id_verified===false){q.importUnsupported=(q.importUnsupported||[]).filter(e=>e!=='Exact production question key is not verified');q.sourceWarnings=['Exact production question key is not verified; local preview ID only']}}}persist()}
refreshProcurementImportMetadata();
